diff --git a/repro/cases.js b/repro/cases.js
new file mode 100644
index 0000000..746c5f1
--- /dev/null
+++ b/repro/cases.js
@@ -0,0 +1,43 @@
+module.exports = {
+  // Exact snippet from the report.
+  report: `export function a() {
+    console.log(o);
+    var o;
+    return o;
+}`,
+  // Same symptom, different trigger: a hoisted function declared after
+  // `var o` reads `o` and runs before `var o`, invoked in a way the current
+  // guard (direct `f()` call textually before the declaration) does not see.
+  directHoistedCall: `function a() {
+    g();
+    var o = 1;
+    function g() { return o; }
+    return o;
+}`,
+  newExpression: `function a() {
+    new F();
+    var o = 1;
+    function F() { this.v = o; }
+    return o;
+}`,
+  indirectHoistedCall: `function a() {
+    h();
+    var o = 1;
+    function g() { return o; }
+    function h() { return g(); }
+    return o;
+}`,
+  callMethod: `function a() {
+    g.call(null);
+    var o = 1;
+    function g() { return o; }
+    return o;
+}`,
+  passedAsCallback: `function a() {
+    [1].forEach(g);
+    var o = 1;
+    function g() { return o; }
+    return o;
+}`,
+  taggedTemplate: "function a() {\n    g``;\n    var o = 1;\n    function g() { return o; }\n    return o;\n}",
+};
diff --git a/repro/run.js b/repro/run.js
new file mode 100644
index 0000000..66cace7
--- /dev/null
+++ b/repro/run.js
@@ -0,0 +1,28 @@
+"use strict";
+// Lints each case with no-var autofix, then executes original and fixed code.
+const path = require("node:path");
+const vm = require("node:vm");
+const lib = process.env.ESLINT_LIB ? require(process.env.ESLINT_LIB) : require(path.join(__dirname, "../lib/api"));
+const linter = new lib.Linter({ configType: "flat" });
+const cases = require("./cases");
+
+function run(code) {
+  try {
+    vm.runInNewContext(code.replace(/^export /mu, "") + "\na();", { console: { log() {} } });
+    return "ok";
+  } catch (e) {
+    return `${e.name}: ${e.message}`;
+  }
+}
+
+let broken = 0;
+for (const [name, code] of Object.entries(cases)) {
+  const r = linter.verifyAndFix(code, [{ rules: { "no-var": "error" } }], { filename: "x.mjs" });
+  const before = run(code), after = r.fixed ? run(r.output) : before;
+  const bad = r.fixed && before === "ok" && after !== "ok";
+  if (bad) broken++;
+  console.log(`--- ${name}: fixed=${r.fixed} original=${before} fixed-output=${after}${bad ? "  <== BUG" : ""}`);
+  if (r.fixed) console.log(r.output);
+}
+console.log(`\n${broken} case(s) where the no-var autofix introduces a ReferenceError (${lib.Linter.version})`);
+process.exitCode = broken ? 1 : 0;
